import{_t as e,it as t,n,rt as r}from"./chunks/framework.Ke88N3OB.js";var i=JSON.parse(`{"title":"Creating an action","description":"Create, document, test, and release a GitHub Action in this repository","frontmatter":{"navigation":{"category":"Getting started"},"title":"Creating an action","description":"Create, document, test, and release a GitHub Action in this repository","editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/docs/creating-an-action.md"},"headers":[],"relativePath":"guides/creating-an-action.md","filePath":"docs/creating-an-action.md","lastUpdated":1792252051000}`),a={name:`guides/creating-an-action.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="creating-an-action" tabindex="-1">Creating an action <a class="header-anchor" href="#creating-an-action" aria-label="Permalink to “Creating an action”">​</a></h1><p>Use the generator to create a GitHub Action scaffold and register it for releases:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gen:action</span></span></code></pre></div><p>The generator asks for a folder name, display name, and one-line description. Use a new kebab-case folder name under <code>actions/</code>; the display name defaults to the folder name with spaces and the first letter of each part capitalized. You can provide all three answers in one command:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gen:action</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --args</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-action</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;My Action&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Does something useful&quot;</span></span></code></pre></div><h2 id="what-the-generator-sets-up" tabindex="-1">What the generator sets up <a class="header-anchor" href="#what-the-generator-sets-up" aria-label="Permalink to “What the generator sets up”">​</a></h2><p>Inside <code>actions/&lt;folder&gt;/</code>, the generator creates <code>action.yml</code> for a JavaScript action that runs <code>src/index.mjs</code> on GitHub&#39;s Node 24 runtime. It also adds a runnable placeholder and smoke test in <code>src/index.mjs</code> and <code>src/index.test.mjs</code>. There is no separate compilation or bundling step.</p><p>It also creates a README, <code>CHANGELOG.md</code>, and <code>version.txt</code>. The README contains generated input and output tables based on <code>action.yml</code>; when the action has no inputs or outputs, it says so explicitly. The generator registers the action in Release Please&#39;s configuration and manifest, and adds it to the Actions table in the root README. It formats the scaffold and release files, but does not commit them.</p><p>Each action has its own release history. The generator pins its first Release Please release to <code>0.0.1</code>, while the initial manifest and <code>version.txt</code> start at <code>0.0.0</code>. Release tags use the action folder name, such as <code>my-action-v0.0.1</code>; later action releases are independent of plugin and other action releases.</p><h2 id="finish-the-action" tabindex="-1">Finish the action <a class="header-anchor" href="#finish-the-action" aria-label="Permalink to “Finish the action”">​</a></h2><ol><li><strong>Declare inputs and outputs</strong> in <code>action.yml</code>, including descriptions that will make sense to someone configuring the action. The README tables are generated from this metadata, so don&#39;t edit those tables by hand.</li><li><strong>Read inputs and write outputs</strong> with the shared <code>getInput()</code> and <code>setOutput()</code> helpers from <code>../../common/src/utils.mjs</code>. Pass the exact input name from <code>action.yml</code> to <code>getInput()</code>, such as <code>getInput(&#39;plugin-name&#39;)</code>. GitHub keeps hyphens in input environment variable names, so <code>plugin-name</code> becomes <code>INPUT_PLUGIN-NAME</code>, not <code>INPUT_PLUGIN_NAME</code>. See the warning in <a href="/pumpkin-plugins/guides/ci-and-releases#registering-an-action-for-releases">CI and releases</a>.</li><li><strong>Implement and test the behavior</strong> in <code>src/index.mjs</code> and <code>src/*.test.mjs</code>. Tests live beside the implementation, and CI tests the actions selected by the changes in your pull request.</li><li><strong>Finish the README</strong> with a human-written overview and usage examples. Then run <code>pnpm readme</code> to refresh the generated input/output tables, reference links, and root Actions table. Use <code>pnpm readme:check</code> to check for generated-documentation drift.</li></ol><p>You can use the action by its folder path and action-specific release tag:</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">steps</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">uses</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">filiphsps/pumpkin-plugins/actions/my-action@my-action-v0.0.1</span></span></code></pre></div><p>GitHub does not automatically list action metadata files nested inside a monorepo in the Marketplace. For the release setup and other publishing details, see <a href="/pumpkin-plugins/guides/ci-and-releases#registering-an-action-for-releases">CI and releases</a>.</p>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};